css:
:root{
  --navy:#20386e; --navy-900:#0d1426; --navy-800:#121c33; --navy-700:#1a2b55;
  --navy-600:#2b4a8c; --navy-400:#5f7cb8; --navy-300:#93a8d2; --navy-50:#eef2f9;
  --red:#cb4236; --red-700:#a3332a; --red-600:#b93a2f; --red-300:#e8776c; --red-50:#fdefed;
  --ink:#101728; --body:#5f6877; --muted:#7a8496;
  --line:#e5e9f1; --line-2:#ccd4e2; --line-dark:rgba(255,255,255,.14);
  --paper:#ffffff; --paper-2:#f5f7fb; --paper-3:#eef2f8;
  --d-ink:#ffffff; --d-body:#c4d0e6; --d-muted:#8e9cba;
  --r-xs:6px; --r-sm:10px; --r:16px; --r-card:22px; --r-lg:32px; --r-xl:46px; --r-pill:999px;
  --sh-1:0 2px 4px rgba(13,20,38,.04);
  --sh-2:0 18px 44px -20px rgba(13,20,38,.3);
  --sh-3:0 40px 90px -34px rgba(13,20,38,.5);
  --gut:clamp(18px,4.4vw,52px);
  --band:clamp(62px,8vw,124px);
  --band-sm:clamp(46px,5.4vw,84px);
  --maxw:1320px;
  --ff-head:"Jost","Jost Fallback","Segoe UI",system-ui,-apple-system,Arial,sans-serif;
  --ff-body:"Montserrat","Montserrat Fallback","Segoe UI",system-ui,-apple-system,Arial,sans-serif;
  --t:.24s; --t-slow:.55s; --ease:cubic-bezier(.4,.16,.2,1);
}
.wrap{width:100%;max-width:var(--maxw);margin-inline:auto;padding-inline:var(--gut)}
.sprite{display:none}
.site-footer .ic{width:18px;height:18px;fill:currentColor}
.site-footer .socials .ic{width:19px;height:19px}
/* ---------- footer ---------- */
.site-footer{position:relative;background:#070c18;color:var(--d-body);font-size:.94rem;overflow:hidden}
.site-footer>*{position:relative;z-index:1}
.site-footer h3{font-family:var(--ff-head);font-size:.8rem;letter-spacing:.17em;text-transform:uppercase;color:#fff;margin:0 0 18px;font-weight:600}
.site-footer h3.after-grid{margin-top:30px}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{margin-bottom:0}
.site-footer a{color:var(--d-body);text-decoration:none;display:inline-block;min-height:34px;padding-block:6px;line-height:1.5;transition:color var(--t) var(--ease)}
.site-footer a:hover{color:#fff;text-decoration:underline}
.f-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.25fr;gap:clamp(28px,3vw,56px);padding-block:clamp(52px,6vw,88px) clamp(40px,4.4vw,64px);align-items:start}
.f-brand img{width:182px;margin-bottom:22px;background:#fff;padding:11px 14px;border-radius:var(--r)}
.f-brand p{max-width:40ch;color:var(--d-muted)}
.site-footer .f-contact{background:rgba(255,255,255,.055);border:1px solid var(--line-dark);border-radius:var(--r-card);padding:18px 20px}
.f-contact li{display:flex;gap:.7em;align-items:flex-start;min-height:34px}
.f-contact li+li{margin-top:6px}
.f-contact span{padding-block:6px;min-width:0}
.f-contact a,.f-contact span{overflow-wrap:anywhere}
.f-contact .ic{color:#fff;background:var(--red);border-radius:50%;padding:6px;width:26px;height:26px;box-sizing:border-box;margin-top:7px;flex:none}
.f-brands{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:14px}
.socials{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}
.socials a{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.09);display:grid;place-items:center;color:#fff;min-height:0;padding:0;transition:background-color var(--t) var(--ease),transform var(--t) var(--ease)}
.socials a:hover{background:var(--red);transform:translateY(-3px)}
.f-bar{border-top:1px solid rgba(255,255,255,.08);padding-top:24px;padding-bottom:clamp(82px,7vw,96px);display:flex;flex-wrap:wrap;gap:10px 30px;justify-content:space-between;align-items:center;font-size:.85rem;color:var(--d-muted)}
.f-bar p{margin:0}
.f-bar ul{display:flex;flex-wrap:wrap;gap:2px 24px}
.f-bar li{margin:0}
.f-bar a{min-height:30px;padding-block:4px}
.built{display:inline-flex;align-items:center;gap:8px;white-space:nowrap;color:var(--d-muted)}
.built img{width:20px;height:20px;flex:none;border-radius:var(--r-xs)}
.built b{color:#fff;font-family:var(--ff-head);font-weight:600}
